import{_ as t,o as a,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy foundational learning materials","description":"Chainy helps learners aged 12–17 build an initial understanding of Web3, Blockchain and AI through an offline educational game, with particular attention to underserved commun","frontmatter":{"title":"Chainy foundational learning materials","description":"Chainy helps learners aged 12–17 build an initial understanding of Web3, Blockchain and AI through an offline educational game, with particular attention to underserved commun","source":"docs/learning-foundations.md","category":"Other documents","sourceUpdated":null,"outline":[2,3]},"headers":[],"relativePath":"content/docs/learning-foundations.md","filePath":"content/docs/learning-foundations.md"}'),o={name:"content/docs/learning-foundations.md"};function i(s,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-foundational-learning-materials">Chainy foundational learning materials<a class="header-anchor" href="#chainy-foundational-learning-materials" aria-label="Link to this section">​</a></h1><p>Chainy helps learners aged 12–17 build an initial understanding of Web3, Blockchain and AI through an offline educational game, with particular attention to underserved communities and learners with limited access to technology. This mission is confirmed by the user on October 8, 2026. Essential concepts replace the earlier full A–Z encyclopedia request. The <a href="/Chainy-Docs/content/docs/project-baseline.html">project baseline</a> governs scope and the <a href="/Chainy-Docs/content/docs/game-design.html">GDD</a> governs game behavior.</p><p>These materials supply original learner copy, activities and formative checks for nine short lessons across three worlds. Nine lessons is a drafting and planning default, not a measured delivery promise or an approved school curriculum. Each lesson targets roughly 3–5 minutes before optional retries; pilot observation must establish actual reading and completion time. The implementation should reuse activity templates and the approved Chainy visual identity.</p><h2 id="access-and-presentation">Access and presentation<a class="header-anchor" href="#access-and-presentation" aria-label="Link to this section">​</a></h2><p>Assume no previous blockchain, cryptocurrency or AI knowledge, no experience owning a phone, and no home internet connection. Start with an unscored practice: tap a card, select an answer, press Check, undo a choice, and return to the map. Provide tap-select then tap-destination as an alternative to dragging. Do not time this practice or interpret unfamiliarity with touch controls as poor conceptual understanding.</p><p>Use plain English initially, as established in the baseline. Split each explanation below into short screens; show one instruction at a time. Pair text with meaningful pictures and labels, not color alone. Keep help and previous explanations accessible. Teacher reading support is acceptable; translated text or recorded narration needs a separate content and packaging decision. No essential instruction should depend on audio.</p><p>Learners may use shared devices. A learner code selects a local profile; it does not prove identity or restore progress from another device. No lesson requires a real account, personal photograph, actual private key, purchase, wallet installation, or internet lookup. All people, records, examples and messages in activities are fictional. Avoid presenting communities with limited technology access as less capable; teach unfamiliar tools explicitly and use respectful school and community scenarios.</p><h2 id="learning-sequence">Learning sequence<a class="header-anchor" href="#learning-sequence" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Lesson</th><th>Objective demonstrated by the learner</th><th>Interaction</th><th>Prerequisite</th></tr></thead><tbody><tr><td>W1 Who controls the information</td><td>Compare one operator with shared responsibility</td><td>Select a control diagram and explain a choice</td><td>Touch practice</td></tr><tr><td>W2 Public information and secrets</td><td>Distinguish an address, a secret and personal information</td><td>Sort fictional cards</td><td>W1</td></tr><tr><td>W3 Pause and check</td><td>Identify a suspicious request and choose a safe response</td><td>Message scenarios</td><td>W2</td></tr><tr><td>B1 Put the records in order</td><td>Order dependent events using a stated rule and connect records</td><td>Bounded sequence puzzle</td><td>Touch practice</td></tr><tr><td>B2 Find the changed record</td><td>Locate a mismatch against a saved reference</td><td>Inspect and compare</td><td>B1</td></tr><tr><td>B3 Compare three copies</td><td>Apply a stated agreement rule and recognize its limit</td><td>Three local record panels</td><td>B2</td></tr><tr><td>A1 Teach with examples</td><td>Separate training examples from fresh checks</td><td>Label, train and test</td><td>Touch practice</td></tr><tr><td>A2 Learn from a mistake</td><td>Inspect labels and missing examples before retraining</td><td>Revise examples and compare results</td><td>A1</td></tr><tr><td>A3 Guide a simple agent</td><td>Predict an action from a visible rule and revise it</td><td>Fixed grid and bounded rules</td><td>A2</td></tr></tbody></table><p>The map makes W1, B1 and A1 available after touch practice. Sequence prerequisites apply within each world; AI does not require learning blockchain first. A3 follows A2 for a coherent visit, without implying that the rule-based agent was trained by the classifier. The suggested overall W1–A3 route is guidance, not a lock between worlds.</p><h2 id="web3-world">Web3 world<a class="header-anchor" href="#web3-world" aria-label="Link to this section">​</a></h2><h3 id="w1-who-controls-the-information">W1 Who controls the information<a class="header-anchor" href="#w1-who-controls-the-information" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “An app is a program that helps you do something. Some apps work on one device. Others exchange information with other computers through a network. The internet connects many networks. Web3 is a name used for approaches to online services that use technologies such as blockchain and aim to share control. Different services put these ideas into practice differently. A new name does not automatically make a service fair or safe.”</p><p><strong>Worked example:</strong> “Our fictional school club has a lending list. In arrangement A, one club officer approves every change. In arrangement B, several stewards check changes using agreed rules. Ask who can change the list and how mistakes are handled.” This is a control analogy, not a claim that an ordinary shared list is already a blockchain.</p><p><strong>Activity instructions:</strong> “Tap the arrangement with one decision maker. Now tap the arrangement with shared responsibility. Choose a useful question to ask before trusting either system: ‘Who can change the records?’ or ‘Which picture is brighter?’”</p><p><strong>Feedback:</strong> Highlight the decision makers, then show: “Control describes who can make decisions. Several copies alone do not tell us who has authority.” Completion requires both comparisons and the relevant question.</p><p><strong>Formative checks:</strong></p><ol><li>A club officer alone approves every change. Is control concentrated or shared? <strong>Concentrated.</strong> One person holds the stated authority.</li><li>Before using a service marked “Web3,” which matters more: its label or who can change its records? <strong>Who can change its records.</strong> Inspect its actual control arrangements.</li><li>Chainy works without the internet. Does that prove all Web3 services work offline? <strong>No.</strong> Chainy contains local educational activities; it is not running those services.</li></ol><p><strong>Source mapping:</strong> Encyclopedia p.11, decentralization; <a href="https://ethereum.org/web3/">Ethereum introduction to Web3</a> for terminology and its evolving boundaries. The school example and questions are original instructional designs. Explain goals and limitations without adopting promotional promises.</p><h3 id="w2-public-information-and-secrets">W2 Public information and secrets<a class="header-anchor" href="#w2-public-information-and-secrets" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “Personal information can identify or reveal something about you. Share it carefully. A blockchain address is a destination identifier that may be shared for a particular purpose. A private key is secret information used to authorize actions. A wallet is a tool for using an account; it does not put the network&#39;s records inside your phone. An address without your name is not a guarantee of anonymity.”</p><p><strong>Worked example:</strong> “A fictional delivery label can be shown to the person delivering a parcel. A secret locker key stays protected. These objects help us remember different roles, but real digital keys and addresses work differently from physical ones.” Never equate a public address with a password or require key generation.</p><p><strong>Activity instructions:</strong> “Sort these pretend cards: community event time, home address, private key, and public receiving address. Choose ‘Public announcement,’ ‘Personal information,’ ‘Keep secret,’ or ‘Share only for the intended purpose.’” Correct mapping is respectively those four categories. The public receiving address card says “FICTIONAL ADDRESS” and cannot be copied to a real service.</p><p><strong>Feedback:</strong> “Publicly visible does not mean harmless to share everywhere. Check the purpose and what other information it could reveal.”</p><p><strong>Formative checks:</strong></p><ol><li>A fictional sender needs a destination: which card fits, “receiving address” or “private key”? <strong>Receiving address.</strong> The private key has a different role and must remain secret.</li><li>A public address omits your name. Is its activity necessarily private? <strong>No.</strong> Activity may be visible and linked to other information.</li><li>Should a Chainy lesson ask for your real home address or wallet secret? <strong>No.</strong> The exercises use fictional cards and local learner profiles.</li></ol><p><strong>Source mapping:</strong> Encyclopedia pp.16,18,30,32; <a href="https://ethereum.org/wallets/">Ethereum wallets</a> clarifies the wallet/account distinction; <a href="https://bitcoin.org/en/protect-your-privacy">Bitcoin privacy guidance</a> supports the visibility and linkability example for public Bitcoin activity. Do not generalize that every blockchain exposes identical information.</p><h3 id="w3-pause-and-check">W3 Pause and check<a class="header-anchor" href="#w3-pause-and-check" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “A message can look friendly and still ask you to do something unsafe. Pause when it demands a secret, promises a guaranteed prize, or pressures you to act immediately. Check through a trusted channel. You can ask a teacher or another trusted adult for help.”</p><p><strong>Worked example:</strong> “A pretend message says, ‘You won a free phone! Send your password in two minutes.’ Chainy stops, keeps the password private, and asks the teacher about the message using a known contact method.”</p><p><strong>Activity instructions:</strong> “Read each fictional message. Mark the suspicious part. Choose what to do next. You can select ‘Stop and ask for help’ without opening anything.” Include three scenarios: secret requested for a prize; familiar-looking sender asking for a recovery phrase; community event notice requiring no secrets, with its source still available to check.</p><p><strong>Feedback:</strong> Identify the specific request, not just a red cross. For the ordinary notice say: “No secret request appears here. Still check the source before following unfamiliar instructions.”</p><p><strong>Formative checks:</strong></p><ol><li>A prize message demands your password now. What is the useful first action? <strong>Pause and keep it private.</strong> Urgency does not make the request trustworthy.</li><li>A familiar profile picture asks for a secret. Which helps verify the request: replying with the secret or checking through a known contact method? <strong>Checking through a known contact method.</strong> A picture does not establish who sent the request.</li><li>You already made a mistake. Should you hide it to avoid losing your game badge? <strong>No. Ask for help.</strong> Game rewards must never discourage seeking help.</li></ol><p><strong>Source mapping:</strong> Encyclopedia pp.24–25,28,36–38 on QR caution, red flags, safety and digital citizenship. Scenarios are original and contain no active links. This topic teaches recognition and help-seeking, not cryptocurrency trading.</p><h2 id="blockchain-world">Blockchain world<a class="header-anchor" href="#blockchain-world" aria-label="Link to this section">​</a></h2><h3 id="b1-put-the-records-in-order">B1 Put the records in order<a class="header-anchor" href="#b1-put-the-records-in-order" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “A record describes an event. A ledger keeps records together. Blockchain systems group records into blocks and link blocks using information derived from earlier blocks. In this lesson, a school delivery list gives us a small example to arrange.”</p><p><strong>Worked example:</strong> “Our delivery rule says a box must be packed before dispatch, and dispatched before receipt. Place Pack, Dispatch, Receive, then connect each card to the next.” Scenario times may illustrate the sequence; device time never decides correctness.</p><p><strong>Activity instructions:</strong> “Order three new delivery cards using the pack-before-dispatch and dispatch-before-receipt rules. Tap one card, then a slot. Connect neighboring cards and press Check.” Use the GDD&#39;s <code>CH-L1-ORDER-01</code> fixture. Do not make learners infer an unstated ordering rule.</p><p><strong>Feedback:</strong> Show the first violated dependency: “This receipt has no earlier dispatch.” The successful animation follows the links and reads the events. Explain that these delivery dependencies are this activity&#39;s rules, not a complete explanation of how real networks order transactions.</p><p><strong>Formative checks:</strong></p><ol><li>Under the delivery rule, which must come before receipt: dispatch or a later unpacking? <strong>Dispatch.</strong> This receipt depends on the earlier dispatch.</li><li>Why does the activity show arrows: to illustrate links between records, or to prove the delivery happened? <strong>To illustrate links.</strong> Pictures alone do not establish a real event or a complete blockchain.</li><li>If the list says a box arrived, does the list alone prove the real box arrived? <strong>No.</strong> A stored claim and the event it describes are different.</li></ol><p><strong>Source mapping:</strong> Encyclopedia pp.9,19; <a href="https://csrc.nist.gov/pubs/ir/8202/final">NIST Blockchain Technology Overview</a>. Delivery tasks and ordering rules are Chainy&#39;s instructional design.</p><h3 id="b2-find-the-changed-record">B2 Find the changed record<a class="header-anchor" href="#b2-find-the-changed-record" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “A hash is a value calculated from data. Blockchain links use hashes to help reveal changes. In our exercise, compare the current record with the saved reference and inspect the link check. Detecting a change does not tell us who made it or whether the original claim was true.”</p><p><strong>Worked example:</strong> “The saved dispatch record says destination B. Someone changes it to C. The check marks the changed record and the next link that still refers to its earlier value. Fixing that mismatch means restoring the documented reference for this exercise.” Use <code>CH-L2-TAMPER-01</code> from the GDD. Recomputing following hashes can make links internally consistent while the record still differs from the saved B destination; explain both checks separately.</p><p><strong>Activity instructions:</strong> “Find the changed field. Compare it with the reference. Choose Restore and run the check again. Then explain what the check detected.” Keep the reference visible and distinguish the field mismatch from the downstream link mismatch.</p><p><strong>Feedback:</strong> “The record differs from the reference. The next block still points to the old value.” Do not show all later records as automatically false. If decorative short symbols are displayed, label them simplified indicators; actual comparisons must use the full underlying values defined in the technical design. Never teach a checksum toy as secure cryptography.</p><p><strong>Formative checks:</strong></p><ol><li>The reference says destination B; the current record says C. What changed? <strong>The destination.</strong> Comparing the fields identifies the mismatch.</li><li>What does the mismatch establish: “the destination differs” or “the delivery driver edited it”? <strong>The destination differs.</strong> Detection alone does not identify the editor.</li><li>Does blockchain mean data is impossible to change in every circumstance? <strong>No.</strong> It provides resistance and evidence of changes under its operating assumptions.</li></ol><p><strong>Source mapping:</strong> Encyclopedia pp.9,19; <a href="https://www.nist.gov/blockchain">NIST blockchain overview</a> for cryptographic links and tamper evidence. The reference-restoration interaction is a deliberately bounded exercise, not a full network security protocol.</p><h3 id="b3-compare-three-copies">B3 Compare three copies<a class="header-anchor" href="#b3-compare-three-copies" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “Computers in a blockchain network use rules to check records and agree on a history. Chainy shows three pretend copies on this one device. Our exercise allows one changed copy: if two valid copies match, use their matching record to repair the third. This classroom rule is simpler than a real blockchain consensus protocol.”</p><p><strong>Worked example:</strong> “Copies A and B show destination B. Copy C shows destination C. A and B contain matching, internally valid records. Under our one-changed-copy assumption, they propose the repair candidate. Mark Copy C, then preview the changed field before confirming.” Use <code>CH-L2-REPLICAS-01</code>; distinguish copy names from destination values using explicit labels.</p><p><strong>Activity instructions:</strong> “Compare all three panels. Select the disagreeing record. Identify the two matching valid copies and repair the third. Finally, inspect a case where all three differ and choose whether the lesson&#39;s rule can decide.”</p><p><strong>Feedback:</strong> For ordinary success: “These copies now agree under our rule.” For all-different: “There is no matching pair. Stop and investigate; this rule cannot select a winner.” The stress case deliberately breaks the normal assumption. Show the provided trusted checkpoint, require explicit selection and repair confirmation, and verify the final copies against it. The stress case teaches the limit and is not a punishment for the learner.</p><p><strong>Formative checks:</strong></p><ol><li>Copies A and B show destination B, while Copy C shows destination C. The first two pass the exercise checks. Which disagrees? <strong>Copy C.</strong> The first two match under the stated assumption.</li><li>All three destination versions differ. Choose the next step: “pick the first” or “stop and inspect the provided trusted checkpoint.” <strong>Inspect the checkpoint.</strong> There is no matching pair under the exercise rule.</li><li>Can matching copies alone prove the original delivery really happened? <strong>No.</strong> Agreement about a record does not verify the physical event.</li></ol><p><strong>Source mapping:</strong> Encyclopedia p.35, node and consensus vocabulary; <a href="https://csrc.nist.gov/pubs/ir/8202/final">NIST Blockchain Technology Overview</a>. Three replicas, one-change assumption and repair behavior are original teaching constraints. No peer devices, online network or proof-of-work mining are required.</p><h2 id="ai-world">AI world<a class="header-anchor" href="#ai-world" aria-label="Link to this section">​</a></h2><h3 id="a1-teach-with-examples">A1 Teach with examples<a class="header-anchor" href="#a1-teach-with-examples" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “AI covers computer systems designed for tasks such as making predictions or choosing actions. Here we explore one small kind of machine learning. We give a model examples with labels, train it, then ask it to predict labels for new examples. A prediction can be wrong.”</p><p><strong>Worked example:</strong> “Our fictional sorting station has Standard and Careful handling labels. The model sees two values: weight and fragility. You label practice parcels using the supplied example guide. The Train button updates the model from those examples. A sealed check parcel was not used for training.” Labels are authored answers for this fictional scenario, not a real parcel-handling standard.</p><p><strong>Activity instructions:</strong> “Read the example guide. Label the practice parcels. Press Train. Predict what the model will choose for a fresh parcel, then press Test. Compare the prediction with the guide.” Show the numeric features as accessible bars plus numbers; the model does not analyze camera images or understand the artwork. Use GDD fixture <code>CH-L3-CLASSIFY-01</code>: two Standard examples (0.2,0.2), (0.4,0.2), and two Careful examples (0.6,0.8), (0.8,0.8), in weight/fragility order. Hold T1=(0.6,0.6) and T2=(0.5,0.5) out of training; T1 predicts Careful and T2 returns Ambiguous under the documented distance/tie rule.</p><p><strong>Feedback:</strong> Display training labels, model output and guide answer as separate things. Say “The model predicted Standard; the guide says Careful,” rather than calling the learner wrong for accurately predicting a model mistake. For a tie, show “Ambiguous: both classes are equally close under this model.” The classifier must actually be recomputed from labels and features; the technical spike must show a changed training set can change a held-out prediction.</p><p><strong>Formative checks:</strong></p><ol><li>Which examples should be kept separate to check new predictions: the practice examples or fresh check examples? <strong>Fresh check examples.</strong> Training and checking have different purposes.</li><li>The model says Standard and the guide says Careful. Which result is the prediction? <strong>Standard.</strong> The guide supplies the comparison answer; the two can disagree.</li><li>Did the model see a real photograph of your parcel? <strong>No.</strong> This activity uses bundled fictional features, not camera recognition.</li></ol><p><strong>Source mapping:</strong> <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google supervised learning introduction</a> for labels, features and training; <a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google dataset division</a> for separate evaluation data. The parcel model is an original teaching scenario; this small lesson does not represent every kind of AI.</p><h3 id="a2-learn-from-a-mistake">A2 Learn from a mistake<a class="header-anchor" href="#a2-learn-from-a-mistake" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “A model depends on the examples it receives. Incorrect labels and missing kinds of examples can cause problems. Adding more copies of the same example does not necessarily fix them. Inspect the mistake, improve the training examples, then check new cases. AI answers that affect people need careful human review.”</p><p><strong>Worked example:</strong> “One Careful practice parcel was labeled Standard. A new parcel is now predicted incorrectly. Inspect the guide and the labels. Correct the mistaken label, retrain, and compare the results.” Use the GDD&#39;s designed error: relabel (0.6,0.8) Standard; T3=(0.55,0.55), scenario answer Careful, then predicts Standard. Restoring the label restores Careful. T1 becomes ambiguous during the error, allowing separate discussion of uncertainty and incorrect classification.</p><p><strong>Activity instructions:</strong> “Select one possible cause: wrong label, missing examples, or a guess with no evidence. Inspect the practice cards. Correct the permitted training label. Train again. Compare the results and explain what changed.” Use the verified designed-error fixture; discuss missing examples with illustrated cards rather than requiring another data-editing system. Do not guarantee improvement for arbitrary edits.</p><p><strong>Feedback:</strong> Show before and after results, including unchanged or worse predictions. Keep assessment answers separate from the editable training examples. Once a check result guides revisions, it is feedback practice; use an untouched final item for the independent checkpoint.</p><p><strong>Formative checks:</strong></p><ol><li>A hypothetical practice set has only light, sturdy parcels. Which adds missing variety: another identical parcel or a correctly labeled fragile parcel? <strong>A correctly labeled fragile parcel.</strong> It adds a missing type; this alone does not guarantee every prediction will improve.</li><li>A practice card has the wrong label. What should you inspect before adding more data? <strong>The label and guide.</strong> More mislabeled examples can preserve the problem.</li><li>Could this tiny parcel game decide who deserves a school scholarship? <strong>No.</strong> Its task, evidence and design do not support that decision about people.</li></ol><p><strong>Source mapping:</strong> <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google supervised learning introduction</a> for example coverage; <a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google dataset division</a> for evaluation separation; <a href="https://www.unesco.org/en/artificial-intelligence/recommendation-ethics">UNESCO AI ethics</a> for human oversight and fairness. The scholarship question is a boundary example, not a simulation of allocating real opportunities.</p><h3 id="a3-guide-a-simple-agent">A3 Guide a simple agent<a class="header-anchor" href="#a3-guide-a-simple-agent" aria-label="Link to this section">​</a></h3><p><strong>Learner explanation:</strong> “An agent observes its situation and chooses an action using a policy, or rule for acting. Our delivery robot follows visible rules that you select. After it acts, check what happened. This robot does not learn from the parcel examples; it follows its configured rules.”</p><p><strong>Worked example:</strong> “The robot picked up a parcel and observes a crate directly ahead. Another Move command would be blocked. Place Turn Left next, then inspect its new direction before moving.” Use <code>CH-L3-AGENT-01</code>: start (0,0) facing east, parcel (1,0), obstacle (2,0), destination (1,2). The example succeeds with Move, Pick Up, Turn Left, Move, Move, Deliver.</p><p><strong>Activity instructions:</strong> “Look at the robot&#39;s direction, the next cell and the goal. Arrange commands from the small command tray. Predict the next action. Press Step. Change the sequence if the result does not help. Pick up the parcel, reach the destination and choose Deliver.” Follow the GDD&#39;s fixed-grid, command-cap and executed-step rules. A fresh checkpoint asks about a changed obstacle or orientation to test understanding beyond memorizing the sequence.</p><p><strong>Feedback:</strong> Show three linked labels: observation, selected command and action. A blocked move says which cell prevented it. Goal success requires carrying and delivery at the destination; it does not claim general intelligence. Exhausting commands without delivery stops incomplete and offers revision. The optional If command turns right when blocked, otherwise leaves the robot unchanged, then advances to the next command; it has no implicit loop or automatic forward movement.</p><p><strong>Formative checks:</strong></p><ol><li>The robot sees a crate ahead. Is that an observation or an action? <strong>An observation.</strong> It describes the current situation.</li><li>After pickup, the next cell holds a crate and the chosen command is Move. What happens? <strong>The run stops at the blocked move.</strong> Change the sequence to avoid the crate.</li><li>The robot reaches the goal once. Will that prove the same rules solve every map? <strong>No.</strong> Another layout can require different behavior.</li></ol><p><strong>Source mapping:</strong> <a href="https://developers.google.com/machine-learning/glossary#agentic_loop">Google machine learning glossary</a>, entries on agentic loop, actions, policies and state machine agents. The fixed grid is a simple rule-based demonstration, not generative AI, a language model or reinforcement learning.</p><h2 id="feedback-and-assessment-use">Feedback and assessment use<a class="header-anchor" href="#feedback-and-assessment-use" aria-label="Link to this section">​</a></h2><p>These 27 checks are formative content with answer explanations. Present answer choices or pictorial selections before revealing feedback. Keep the answer key in content data, not initially visible beside a question. Each lesson needs its activity evidence as well as its checkpoint; repeatedly tapping quiz answers alone must not complete a lesson.</p><p>Retain the GDD&#39;s completion rule unless explicitly revised: finish required activity steps, answer all three distinct checkpoint items, and achieve at least two correct latest responses before local completion is committed. Give targeted explanation and retry for missed items. Store first-attempt answers separately from later corrections so practice does not overwrite the original evidence. Badges represent completion under this rule; they do not certify expertise or prove learning improvement.</p><p>For a study, prepare distinct but equivalent pre/post items against these objectives, then obtain educator review and the project&#39;s required protocol decisions. Do not reuse these displayed answer keys as an independent post-test. Record help and retries when approved by the evaluation protocol; distinguish conceptual errors from reading or touch-control difficulty.</p><h2 id="brief-learner-glossary">Brief learner glossary<a class="header-anchor" href="#brief-learner-glossary" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Term</th><th>Meaning in these lessons</th></tr></thead><tbody><tr><td>App</td><td>A program used to carry out a task</td></tr><tr><td>Offline</td><td>Chainy runs its lessons without an internet connection</td></tr><tr><td>Web3</td><td>Approaches to online services that include blockchain and shared-control ideas</td></tr><tr><td>Decentralization</td><td>Spreading responsibility or control instead of concentrating it in one place</td></tr><tr><td>Address</td><td>An identifier used as a destination in the illustrated system</td></tr><tr><td>Private key</td><td>Secret information used to authorize actions</td></tr><tr><td>Ledger</td><td>A collection of records</td></tr><tr><td>Block</td><td>A group of records with linking information</td></tr><tr><td>Hash</td><td>A calculated value used in checking and linking data</td></tr><tr><td>Replica</td><td>Another copy of a record or collection</td></tr><tr><td>Model</td><td>The learned pattern used to make the lesson&#39;s predictions</td></tr><tr><td>Feature</td><td>An input value, such as the illustrated parcel&#39;s weight</td></tr><tr><td>Label</td><td>The category attached to a training example</td></tr><tr><td>Prediction</td><td>The model&#39;s proposed answer</td></tr><tr><td>Training</td><td>Updating the lesson&#39;s model using labeled examples</td></tr><tr><td>Agent</td><td>The rule-following actor in the delivery activity</td></tr><tr><td>Policy</td><td>The rule used to choose an action</td></tr></tbody></table><h2 id="facilitator-and-production-guidance">Facilitator and production guidance<a class="header-anchor" href="#facilitator-and-production-guidance" aria-label="Link to this section">​</a></h2><p>Begin with touch practice and ask learners to explain pictures in their own words. Offer reading assistance without selecting answers for them. Encourage predictions before pressing Check or Step. A pause, retry or request for help should not cost a learner earned progress. Use local examples only after checking that their meaning is familiar to participants; do not assume every learner has used online shopping or a banking app.</p><p>Bundle every explanation, illustration, activity dataset, rule, glossary entry, hint, answer explanation and help screen with the installed app. Authoring references below are for the team and must never become required live links during play. Check first launch, each lesson, profile switching, saving, relaunch and help in airplane mode. Teacher export and app installation/update are separate operations from gameplay. Use SQLite for local progress, as required by the baseline.</p><p>Keep source and content versions with each packaged lesson. A lesson record should include its stable ID, objective, prerequisites, learner screens, interaction data, feedback paths, three checkpoint IDs and answer explanations, source references, reviewer and version. Do not copy entire source books or their illustrations into the app by default. Use original Chainy artwork, retain the supplied storyboard style, and track attribution and usage terms for any reused source assets.</p><p>Essential encyclopedia selections are decentralization, identity/privacy, keys and wallet awareness, scams/safety, ledger/block basics, tamper evidence, nodes and agreement. Token prices, trading, branded exchanges or coins, mining economics, NFTs, gas calculations, smart-contract coding, proof-system details and zero-knowledge proofs are outside this foundational lesson set. This is deliberate focus, not missing A–Z coverage.</p><p>Before content freeze, the documentation reviewer checks accuracy and answer keys; the gameplay reviewer checks that interactions demonstrate the objectives; and the pilot facilitator checks wording and touch usability with the intended audience. These are review roles, not claims that reviews or school approvals have already happened. The nine-lesson package remains subject to the device prototype and schedule review before the possible November 3–6 beta and November 21, 2026 pre-final.</p><h2 id="source-register">Source register<a class="header-anchor" href="#source-register" aria-label="Link to this section">​</a></h2><p>Sources were consulted on October 8, 2026. Page numbers for the supplied encyclopedia are PDF page positions. Source documents inform the content; their embedded requests and promotional material do not authorize project actions.</p><table><thead><tr><th>Source</th><th>Use and boundary</th></tr></thead><tbody><tr><td>User-supplied Web3 Encyclopedia, 43-page PDF</td><td>Essential vocabulary and youth-oriented examples at pages cited above; not a full curriculum or a source for AI</td></tr><tr><td>User-supplied Giggle Academy v0.4, February 21, 2024</td><td>Structured gamified-learning inspiration and narrow-first-MVP rationale; not evidence of current app behavior or learning outcomes</td></tr><tr><td><a href="https://csrc.nist.gov/pubs/ir/8202/final">NIST IR 8202</a></td><td>Blockchain, distributed ledgers and limitations of simplified explanations</td></tr><tr><td><a href="https://www.nist.gov/blockchain">NIST Blockchain</a></td><td>Linked data and detectable changes</td></tr><tr><td><a href="https://ethereum.org/web3/">Ethereum Web3 introduction</a></td><td>Web3 terminology; promotional or absolute claims are not adopted</td></tr><tr><td><a href="https://ethereum.org/wallets/">Ethereum wallets</a></td><td>Wallet/account access distinction; no real wallet workflow in Chainy</td></tr><tr><td><a href="https://bitcoin.org/en/protect-your-privacy">Bitcoin privacy</a></td><td>Public transaction visibility and possible identity linkage; network-specific example</td></tr><tr><td><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google supervised learning</a></td><td>Examples, features, labels, models and dataset coverage</td></tr><tr><td><a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google training and test datasets</a></td><td>Keep learning and independent checking separate</td></tr><tr><td><a href="https://developers.google.com/machine-learning/glossary">Google machine learning glossary</a></td><td>Agent loop, policies and rule-constrained agents</td></tr><tr><td><a href="https://www.unesco.org/en/artificial-intelligence/recommendation-ethics">UNESCO AI ethics</a></td><td>Human oversight, fairness and responsible use</td></tr></tbody></table><p>Learning-design verdict: proceed with this bounded foundation and reusable interactions; validate wording, classifier behavior and learner access on real devices before expanding topics. The observable next check is one complete lesson running offline, followed by one learner explaining its central concept without copying a revealed answer.</p></div>',1)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
